import{_ as n,C as a,o as i,c as s,E as r,a2 as d}from"./chunks/framework.DyLyN3RJ.js";const f=JSON.parse('{"title":"最小授权可能不止一个：审批还缺少哪项选择依据","description":"","frontmatter":{"title":"最小授权可能不止一个：审批还缺少哪项选择依据","date":"2026-11-07","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"同一任务存在不可比的最小充分授权时，风险评分与审批应保留什么选择信息？","summary":"合成穷举保留了两个不可比的最小授权；审批需要同时说明实际权限足迹与选择目标。","sources":"https://arxiv.org/html/2610.31914v1","pageClass":"runtime-v6-article","item_id":"SIG-20261107-007","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-07-sig-20261107-007-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-11-07-sig-20261107-007.md","filePath":"zh/industry/2026-11-07-sig-20261107-007.md","lastUpdated":1794053614000}'),c={name:"zh/industry/2026-11-07-sig-20261107-007.md"};function l(p,e,h,u,m,_){const t=a("ArticleCover"),o=a("ArticleTableScroll");return i(),s("div",null,[r(t,{image:"/assets/covers/daily-2026-11-07-sig-20261107-007-cover.png",kicker:"研究成果",title:"最小授权可能不止一个：审批还缺少哪项选择依据",summary:"合成穷举保留了两个不可比的最小授权；审批需要同时说明实际权限足迹与选择目标。",version:"2026-11-07",languageHref:"/en/industry/2026-11-07-sig-20261107-007",languageLabel:"English"}),r(o,{language:"zh"}),e[0]||(e[0]=d('<h1 id="最小授权可能不止一个-审批还缺少哪项选择依据" tabindex="-1">最小授权可能不止一个：审批还缺少哪项选择依据 <a class="header-anchor" href="#最小授权可能不止一个-审批还缺少哪项选择依据" aria-label="Permalink to &quot;最小授权可能不止一个：审批还缺少哪项选择依据&quot;">​</a></h1><p>一个任务只需要读取操作，但现有授权分别附带另一项不同权限。两种授权都足以完成任务，也都无法再缩减，审批人却仍然必须选一个。“已经最小化”没有回答究竟接受了哪一种额外能力。这是权限选择系统需要解释的决定，而非一个通过最小性检查就能消失的问题。</p><p>同日研究中的合成穷举给出了一个小而完整的反例：去除等价授权后，仍有两个互不包含的最小权限足迹。本文的判断因此限于机制层面：选择记录应保留任务、足迹、比较目标和理由。它不估计真实业务中这种情况的发生率。</p><h2 id="最小不等于唯一最少" tabindex="-1">最小不等于唯一最少 <a class="header-anchor" href="#最小不等于唯一最少" aria-label="Permalink to &quot;最小不等于唯一最少&quot;">​</a></h2><p>论文把授权的权限足迹定义为所覆盖操作的并集，以集合包含关系比较授权。这里的“最小”意味着找不到严格更小且仍能完成任务的足迹；“唯一最少”则要求一个足迹包含于所有其他充分足迹。前者允许多个互不包含的答案。<a href="https://arxiv.org/html/2610.31914v1" target="_blank" rel="noreferrer">论文，第 3、5、7 节</a></p><p>这一差别还区分了授权名称与实际能力。两个名称可能覆盖同一足迹，应先合并等价情况；两个同级风险标签也可能覆盖不同操作，不能据此合并。否则，评分系统会把“同一个答案的别名”与“风险取舍不同的答案”混在一起。</p><h2 id="一个读取任务留下两个答案" tabindex="-1">一个读取任务留下两个答案 <a class="header-anchor" href="#一个读取任务留下两个答案" aria-label="Permalink to &quot;一个读取任务留下两个答案&quot;">​</a></h2><p>内部合成实验只使用四个授权名称：两个都覆盖集合 <code>{read, x}</code>，第三个覆盖 <code>{read, y}</code>，第四个覆盖 <code>{read, x, y}</code>；任务只要求 <code>{read}</code>。枚举得到 15 个充分授权组合，合并后有 3 个不同足迹，其中 <code>{read, x}</code> 与 <code>{read, y}</code> 都是最小值。它们各含对方没有的操作，因此不能用包含关系决定孰优。</p><p>当额外操作的代价分别设为 <code>x=10, y=1</code>，选择落在带有 <code>y</code> 的授权；交换代价后，选择随之反转。两次都满足最小性，变化来自明确的比较目标，而非授权忽然变得不充分。增加只覆盖 <code>{read}</code> 的精细授权作为对照后，31 个充分组合归为 4 个足迹，出现唯一最小值。</p><p>这些是本研究的内部实验依据，不是独立复现。实验只检查论文定义下的合成集合与显式权重，没有运行真实接口、模型授权请求或资源条件。其原始结果与实验限定见<a href="/joinwell52/assets/evidence/2026-11-07-sig-20261107-007/authority-experiment.json">实验记录</a>。它能够说明评分漏掉了什么信息，不能说明某一种权重是安全政策的正确答案。</p><h2 id="询问时机与选择理由属于不同层次" tabindex="-1">询问时机与选择理由属于不同层次 <a class="header-anchor" href="#询问时机与选择理由属于不同层次" aria-label="Permalink to &quot;询问时机与选择理由属于不同层次&quot;">​</a></h2><p>研究对象还检查了 OpenHands（开放智能体软件开发工具）的风险确认策略。该实现的确认方法返回布尔值，默认阈值为高风险，对未知风险默认要求确认。它回答何时询问，没有枚举充分授权，也没有替审批人选择不可比的最小值。<a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/main/openhands-sdk/openhands/sdk/security/confirmation_policy.py" target="_blank" rel="noreferrer">官方实现，确认方法</a></p><p>因此，我们的解释是：提高确认频率与解释授权取舍可以同时需要，却不能相互替代。即使每次都弹出确认，如果只展示单个风险等级，审批人仍无法知道另一个充分授权保留了什么能力。反过来，列出权限足迹也没有自动决定哪些请求必须人工介入。</p><p>可追责的选择记录至少应说明这次任务、所选实际足迹、仍可行的不可比替代项，以及偏好更窄覆盖还是更少状态变更等目标。这里建议的是记录选择责任的方式，尚未测试部署收益，也不要求把所有权限组合原样交给用户。</p><h2 id="不能把目录比例当作部署频率" tabindex="-1">不能把目录比例当作部署频率 <a class="header-anchor" href="#不能把目录比例当作部署频率" aria-label="Permalink to &quot;不能把目录比例当作部署频率&quot;">​</a></h2><p>论文报告，在其生成的任务族中，一类微软权限任务有 147/493 个出现非唯一最小值，谷歌资源任务为 90/2822 个。这些分母来自不同目录和任务构造，不能直接解释为两个平台在生产环境里的安全发生率。论文的模型实验也向模型提供封闭的充分授权选项，不能把报告的最小性比例解释为自由运行请求的成功率。<a href="https://arxiv.org/html/2610.31914v1" target="_blank" rel="noreferrer">论文，第 6、9、11、14 节</a></p><p>同样重要的是反向约束：论文报告的谷歌合成工作流中，逐步选择最窄最小授权有 98.8%—99.5% 到达全流程最小值。这限制了“权限差异全由逐步累积造成”的叙事。本文的反例针对单次选择歧义，并未证实累积一定导致过度授权。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文使用三种不同依据：论文中的数字与定义属于来源陈述；公开代码说明被检查的确认方法做了什么；合成集合穷举是内部实验依据。没有独立第三方重现论文结果，引用或论文公开均不构成验证。成功运行一个小实验也不建立普遍有效性。</p><p>主要来源为 <a href="https://arxiv.org/html/2610.31914v1" target="_blank" rel="noreferrer">arXiv（开放研究预印本平台）论文《智能体工具授权中的不可比最小值》，第一版，第 3—14 节</a>，以及 <a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/main/openhands-sdk/openhands/sdk/security/confirmation_policy.py" target="_blank" rel="noreferrer">OpenHands 官方确认策略源码</a>。预印本编号为 2610.31914，标题采用中文译名。来源快照于本次研究中按内容哈希固定，源码分支并非已知的基准发布提交。内部实验记录保留了输入、穷举结果、权重与对照；它没有取得或复现作者数据包。</p><h2 id="资源条件加入之后还剩哪些选择" tabindex="-1">资源条件加入之后还剩哪些选择 <a class="header-anchor" href="#资源条件加入之后还剩哪些选择" aria-label="Permalink to &quot;资源条件加入之后还剩哪些选择&quot;">​</a></h2><p>方法级目录忽略资源级限制与条件，实际任务分布也未在本研究中测量。更精细的目录能够像合成对照一样消除某些歧义，但不能由此推断所有真实授权都有唯一最小值。下一步需要的是带资源条件的固定目录、真实任务足迹与明确的风险目标，才能判断哪些替代项应展示给审批人，以及谁对目标负责。</p>',22))])}const b=n(c,[["render",l]]);export{f as __pageData,b as default};
